package com.togoptimizer;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * The continue countdown just above Juna's dialogue, where the player is looking while it's open.
 */
class ContinueOverlay extends Overlay
{
	private static final int GAP = 6;

	private final Client client;
	private final TogOptimizerPlugin plugin;
	private final TogOptimizerConfig config;

	@Inject
	private ContinueOverlay(Client client, TogOptimizerPlugin plugin, TogOptimizerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showEntryTiming() || plugin.getUnlockAt() != null || plugin.getRequirement() != null)
		{
			return null;
		}
		String cue = JunaOverlay.continueCue(plugin);
		Widget dialogue = client.getWidget(InterfaceID.ChatLeft.TEXT);
		if (cue == null || dialogue == null || dialogue.isHidden())
		{
			return null;
		}
		Rectangle bounds = dialogue.getBounds();
		int width = graphics.getFontMetrics().stringWidth(cue);
		Point location = new Point(bounds.x + (bounds.width - width) / 2, bounds.y - GAP);
		OverlayUtil.renderTextLocation(graphics, location, cue, JunaOverlay.cueColour(cue));
		return null;
	}
}

package com.togoptimizer;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;

/**
 * When the minigame can next be played. The OSRS Wiki: Juna resets at the start of the 7th day after
 * the last game, and the player must also have gained 100,000 experience or a quest point since.
 * Days start at the game's daily reset, midnight UTC.
 */
final class Eligibility
{
	static final int DAYS = 7;
	static final long XP_NEEDED = 100_000;
	// Juna's replies when asked too early: "...Come back in 7 days." after a story, and "It has not been
	// long since your last visit. Come again in 7 days." from the Story option
	private static final Pattern COME_BACK = Pattern.compile("come (?:back|again) in (\\d+) days?", Pattern.CASE_INSENSITIVE);
	private static final Pattern TOMORROW = Pattern.compile("come (?:back|again) tomorrow", Pattern.CASE_INSENSITIVE);

	private Eligibility()
	{
	}

	/**
	 * @return when a game finishing at {@code gameEnd} lets the player play again
	 */
	static long unlockAfterGame(long gameEnd)
	{
		return startOfDay(gameEnd, DAYS);
	}

	/**
	 * @return when the player can play again if Juna says to come back in {@code days} days
	 */
	static long unlockInDays(int days, long now)
	{
		return startOfDay(now, days);
	}

	private static long startOfDay(long millis, int daysLater)
	{
		LocalDate day = Instant.ofEpochMilli(millis).atZone(ZoneOffset.UTC).toLocalDate();
		return day.plusDays(daysLater).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
	}

	/**
	 * @return the days Juna says to come back in, or null if the text isn't that reply
	 */
	@Nullable
	static Integer daysFromJuna(String text)
	{
		Matcher matcher = COME_BACK.matcher(text);
		if (matcher.find())
		{
			return Integer.parseInt(matcher.group(1));
		}
		return TOMORROW.matcher(text).find() ? 1 : null;
	}

	/**
	 * @return time left as days, hours and minutes, such as "6d 9h 55m"
	 */
	static String formatRemaining(long millis)
	{
		long minutes = Math.max(0, (millis + 59_999) / 60_000);
		long days = minutes / (24 * 60);
		long hours = minutes / 60 % 24;
		long mins = minutes % 60;
		if (days > 0)
		{
			return days + "d " + hours + "h " + mins + "m";
		}
		return hours > 0 ? hours + "h " + mins + "m" : mins + "m";
	}

	/**
	 * @param qpRequired the quest points needed to play again, from the game; 0 if there's no requirement
	 * @param xpAtLastGame total experience when the last game ended, or null if the plugin didn't see it
	 * @return what's still needed, or null if the experience or quest point condition is met
	 */
	@Nullable
	static String requirement(int qpRequired, int questPoints, long totalXp, @Nullable Long xpAtLastGame)
	{
		if (qpRequired <= 0 || questPoints >= qpRequired)
		{
			return null;
		}
		int qp = qpRequired - questPoints;
		String questPointText = qp + " more quest point" + (qp == 1 ? "" : "s");
		if (xpAtLastGame == null)
		{
			return "Needs " + questPointText + " or 100,000 XP since your last game";
		}
		long xp = XP_NEEDED - (totalXp - xpAtLastGame);
		if (xp <= 0)
		{
			return null;
		}
		return "Needs " + questPointText + " or " + String.format("%,d", xp) + " XP";
	}
}

package com.togoptimizer;

/**
 * When to continue past Juna's last line, which lets the player into the cave, so the game starts at a
 * good point in the stream cycle. Her earlier lines take however long the player takes to click
 * through, but the last one waits, so timing the final click is reliable.
 *
 * Simulations found the most tears when the first blue of a cycle moves one tick after the player
 * enters, and within about 1.5 tears of that from one tick before to two after.
 */
final class EntryTiming
{
	// Ticks from continuing past Juna's last line to the game starting, estimated from one game where the
	// whole story took 15 ticks. The debug log records both, to refine it.
	static final int CONTINUE_TICKS = 3;
	// Her last line before letting the player in
	static final String LAST_LINE = "I will let you into the cave";
	// When the first blue moves relative to the player entering, from one tick before to two after
	private static final int EARLIEST_ENTRY = -1;
	private static final int LATEST_ENTRY = 2;

	private EntryTiming()
	{
	}

	/**
	 * @return the tick the first blue of the cycle next moves, or -1 if no blue is known
	 */
	static int firstBlueMove(int[] colour, int[] nextMove)
	{
		int first = -1;
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			if (colour[wall] != TearsGame.BLUE || nextMove[wall] < 0)
			{
				continue;
			}
			// The first blue of a burst has no blue moving the tick before it; a blue that moved on that
			// tick is already a whole cycle further on
			boolean follows = false;
			for (int other = 0; other < Walls.COUNT; other++)
			{
				if (colour[other] == TearsGame.BLUE && other != wall
					&& (nextMove[other] == nextMove[wall] - 1 || nextMove[other] == nextMove[wall] - 1 + TearsGame.STREAM_LIFE))
				{
					follows = true;
					break;
				}
			}
			if (!follows && (first < 0 || nextMove[wall] < first))
			{
				first = nextMove[wall];
			}
		}
		return first;
	}

	/**
	 * @return 0 if continuing past Juna's last line now starts the game at a good time, otherwise the
	 * ticks to wait
	 */
	static int ticksUntilContinue(int firstBlueMove, int tick)
	{
		// How many ticks after entering the first blue would move, if the player continued now
		int entry = Math.floorMod(firstBlueMove - tick - CONTINUE_TICKS, TearsGame.STREAM_LIFE);
		if (entry > TearsGame.STREAM_LIFE / 2)
		{
			entry -= TearsGame.STREAM_LIFE;
		}
		if (entry >= EARLIEST_ENTRY && entry <= LATEST_ENTRY)
		{
			return 0;
		}
		// Waiting a tick moves the entry one tick later in the cycle, bringing the first blue one closer
		return Math.floorMod(entry - LATEST_ENTRY, TearsGame.STREAM_LIFE);
	}
}

package com.togoptimizer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Above Juna: whether this world moves its streams in the best order, better worlds if not, and when
 * to enter so the game starts at a good time.
 */
class JunaOverlay extends Overlay
{
	private static final int LINE_HEIGHT = 15;
	private static final int TEXT_HEIGHT = 300;

	private final Client client;
	private final TogOptimizerPlugin plugin;
	private final TogOptimizerConfig config;

	@Inject
	private JunaOverlay(Client client, TogOptimizerPlugin plugin, TogOptimizerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/**
	 * @return the countdown for continuing past Juna's last line, or null if it isn't on screen
	 */
	static String continueCue(TogOptimizerPlugin plugin)
	{
		if (!plugin.isJunasLastLine())
		{
			return null;
		}
		int wait = plugin.ticksUntilContinue();
		if (wait < 0)
		{
			return "Continue: timing the streams...";
		}
		return wait == 0 ? "Continue now" : "Continue in " + wait;
	}

	static Color cueColour(String cue)
	{
		if (cue.equals("Continue now"))
		{
			return Color.GREEN;
		}
		return cue.startsWith("Continue in") ? Color.WHITE : Color.LIGHT_GRAY;
	}

	private String describeWorld(int world)
	{
		Integer ping = plugin.pingOf(world);
		return ping == null ? String.valueOf(world) : world + " (" + ping + " ms)";
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.inCave())
		{
			return null;
		}
		GameObject juna = plugin.getJuna();
		if (juna == null)
		{
			return null;
		}

		List<String> texts = new ArrayList<>();
		List<Color> colours = new ArrayList<>();

		String order = plugin.worldOrder();
		boolean optimal = StreamTracker.OPTIMAL_ORDER.equals(order);
		if (config.showWorldStatus())
		{
			if (order == null)
			{
				texts.add("Watching the streams...");
				colours.add(Color.LIGHT_GRAY);
			}
			else if (optimal)
			{
				texts.add("Best stream order (gggbbb)");
				colours.add(Color.GREEN);
				Integer faster = plugin.getFasterWorld();
				if (faster != null)
				{
					texts.add("Faster gggbbb world: " + describeWorld(faster) + ", this world "
						+ plugin.pingOf(plugin.currentWorld()) + " ms");
					colours.add(Color.WHITE);
				}
			}
			else
			{
				texts.add("Stream order " + order + ", not gggbbb");
				colours.add(Color.RED);
				List<Integer> worlds = plugin.getSuggestions();
				if (!worlds.isEmpty())
				{
					texts.add("gggbbb worlds: " + worlds.stream().map(this::describeWorld).collect(Collectors.joining(", ")));
					colours.add(Color.WHITE);
				}
			}
		}

		Long unlock = plugin.getUnlockAt();
		String requirement = plugin.getRequirement();
		if (config.showNextGame() && unlock != null)
		{
			texts.add("Next game in " + Eligibility.formatRemaining(unlock - System.currentTimeMillis()));
			colours.add(Color.ORANGE);
		}
		if (config.showRequirement() && requirement != null)
		{
			texts.add(requirement);
			colours.add(Color.ORANGE);
		}

		// Entry timing only matters when the player can actually play
		boolean canPlay = unlock == null && requirement == null;
		if (config.showEntryTiming() && optimal && canPlay && !plugin.playerInRoom())
		{
			String cue = continueCue(plugin);
			if (cue != null)
			{
				texts.add(cue);
				colours.add(cueColour(cue));
			}
			else
			{
				texts.add("Tell story, then wait on Juna's last line");
				colours.add(Color.WHITE);
			}
		}

		for (int i = 0; i < texts.size(); i++)
		{
			Point location = Perspective.getCanvasTextLocation(client, graphics, juna.getLocalLocation(), texts.get(i), TEXT_HEIGHT);
			if (location != null)
			{
				OverlayUtil.renderTextLocation(graphics, new Point(location.getX(), location.getY() + i * LINE_HEIGHT),
					texts.get(i), colours.get(i));
			}
		}
		return null;
	}
}

package com.togoptimizer;

import java.util.Arrays;
import java.util.Random;
import lombok.Value;

/**
 * Estimates how many tears each choice of wall leads to, by playing the same random futures out
 * from each choice and averaging.
 */
final class Planner
{
	@Value
	static class Plan
	{
		// Expected tears over the horizon if the player picks each wall now; NaN where it isn't an option
		double[] expected;
		// The wall with the most expected tears, or -1 if there is no choice to make
		int best;
	}

	// How much better another wall must be before the recommendation moves to it, in tears. Two walls'
	// values cross as streams age; at 0.5 the highlight reversed about 12 times a game, at 1.5 about
	// once, with no measurable cost in tears.
	static final double STEADY_MARGIN = 1.5;
	// The six streams move on consecutive ticks, so a cycle's remaining moves all fall within this many
	private static final int BURST_TICKS = 5;

	private final int rollouts;
	private final int horizon;

	Planner(int rollouts, int horizon)
	{
		this.rollouts = rollouts;
		this.horizon = horizon;
	}

	/**
	 * @param game the current game, after this tick's streams have moved
	 */
	Plan plan(TearsGame game, long seed)
	{
		double[] expected = new double[Walls.COUNT];
		Arrays.fill(expected, Double.NaN);

		Random seeds = new Random(seed);
		long[] futures = new long[rollouts];
		for (int i = 0; i < rollouts; i++)
		{
			futures[i] = seeds.nextLong();
		}

		int best = -1;
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			if (!isOption(game, wall))
			{
				continue;
			}

			long total = 0;
			for (long future : futures)
			{
				TearsGame sim = game.copy(new Random(future));
				int start = sim.tears;
				// Choosing this option replaces any click already on its way
				sim.pendingWall = -1;
				sim.request(wall);
				sim.finishTick();
				sim.runUntil(game.tick + horizon, TearsGame::nearestBlue);
				total += sim.tears - start;
			}
			expected[wall] = total / (double) rollouts;
			if (best < 0 || expected[wall] > expected[best])
			{
				best = wall;
			}
		}
		return new Plan(expected, best);
	}

	/**
	 * Keeps showing the previous choice while it's still an option within {@code margin} tears of the
	 * best, so near-ties don't make the recommendation flicker between walls.
	 */
	static int steady(int previous, Plan plan, double margin)
	{
		int best = plan.getBest();
		if (previous < 0 || best < 0)
		{
			return best;
		}
		double[] expected = plan.getExpected();
		return !Double.isNaN(expected[previous]) && expected[previous] >= expected[best] - margin ? previous : best;
	}

	/**
	 * How long waiting at an empty wall can still pay off: blues can only land when they move, and a
	 * cycle's moves come on consecutive ticks, so once the last blue due soon has moved, there's no
	 * point waiting any longer.
	 *
	 * @return ticks until the last blue due to move in the current burst, or -1 if none is due
	 */
	static int waitTicks(TearsGame game)
	{
		int last = -1;
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			int due = game.nextMove[wall] - game.tick;
			if (game.colour[wall] == TearsGame.BLUE && due > 0 && due <= BURST_TICKS)
			{
				last = Math.max(last, due);
			}
		}
		return last;
	}

	/**
	 * Any blue wall, or the empty wall the player is already at while a blue could still land there
	 */
	private static boolean isOption(TearsGame game, int wall)
	{
		return game.colour[wall] == TearsGame.BLUE
			|| wall == game.target && game.colour[wall] == TearsGame.NONE && waitTicks(game) > 0;
	}

	/**
	 * @return ticks left to wait if {@code shown} means staying at the player's own empty wall, or -1
	 */
	static int waitTicksFor(TearsGame game, int shown)
	{
		boolean waiting = shown >= 0 && shown == game.target && game.colour[shown] == TearsGame.NONE;
		return waiting ? waitTicks(game) : -1;
	}

	/**
	 * Follows the planner's advice whenever the current wall stops giving blue tears.
	 */
	TearsGame.Policy asPolicy(long seed)
	{
		// Separate from the game's own randomness, so the game plays out the same as under other policies
		Random seeds = new Random(seed);
		return game ->
		{
			if (game.target >= 0 && game.colour[game.target] == TearsGame.BLUE)
			{
				return -1;
			}
			return plan(game, seeds.nextLong()).getBest();
		};
	}
}

package com.togoptimizer;

import lombok.Getter;

/**
 * A simulated player following the plugin's advice on the real streams, so the plugin can be seen
 * working from outside the wall room without spending a game.
 */
final class PreviewRun
{
	@Getter
	private final TearsGame player;
	private final Planner planner;
	private final long seed;
	@Getter
	private Planner.Plan plan;
	// The planner's choice, held steady through near-ties like the highlight a player would follow
	@Getter
	private int shown = -1;
	@Getter
	private int waitTicks = -1;

	PreviewRun(int startTick, int ticks, int startX, int startY, int reaction, Planner planner, long seed)
	{
		player = new TearsGame();
		player.tick = startTick;
		player.endTick = startTick + ticks;
		player.x = startX;
		player.y = startY;
		player.reaction = reaction;
		this.planner = planner;
		this.seed = seed;
	}

	boolean isOver()
	{
		return player.over();
	}

	/**
	 * Advances the player through a tick of the real game, after its streams have moved.
	 */
	void tick(StreamTracker tracker, int tick)
	{
		if (isOver())
		{
			return;
		}

		player.tick = tick;
		tracker.fill(player);
		// The same futures every tick, so the estimates don't jitter from one tick to the next
		plan = planner.plan(player, seed);
		shown = Planner.steady(shown, plan, Planner.STEADY_MARGIN);
		// Worked out before the tick finishes, while the game still shows this tick's streams
		waitTicks = Planner.waitTicksFor(player, shown);
		// Moves whenever the shown wall changes, as a player following it would
		player.request(shown);
		player.finishTick();
	}
}

package com.togoptimizer;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import javax.annotation.Nullable;

/**
 * Follows the streams on the weeping walls: their colours, when each will next move, and the order
 * the world moves them in.
 *
 * Streams present when the cave loads all appear on the same tick, so how long they have left is
 * unknown until they next move. A real move is one stream on one tick, and all six move on
 * consecutive ticks once per cycle, so after one cycle everything is known.
 */
final class StreamTracker
{
	// The order that makes green tears easiest to avoid: all three greens move before the blues
	static final String OPTIMAL_ORDER = "gggbbb";
	private static final int UNKNOWN = Integer.MIN_VALUE;
	private static final int STREAMS = 6;

	private final int[] colour = new int[Walls.COUNT];
	private final int[] spawnTick = new int[Walls.COUNT];

	// Walls a stream appeared on this tick, to tell a cave load (several at once) from a move (one)
	private int spawnsTick = UNKNOWN;
	private final Deque<Integer> spawnsThisTick = new ArrayDeque<>();

	// Recent moves as {tick, colour}, to spot a full cycle of six on consecutive ticks
	private final Deque<int[]> moves = new ArrayDeque<>();
	@Nullable
	private String order;
	private int lastLife = UNKNOWN;

	StreamTracker()
	{
		reset();
	}

	void reset()
	{
		Arrays.fill(colour, TearsGame.NONE);
		Arrays.fill(spawnTick, UNKNOWN);
		spawnsTick = UNKNOWN;
		spawnsThisTick.clear();
		moves.clear();
		order = null;
		lastLife = UNKNOWN;
	}

	/**
	 * A wall started showing a colour ({@link TearsGame#NONE} when its stream left).
	 */
	void wallChanged(int wall, int newColour, int tick)
	{
		if (newColour == TearsGame.NONE)
		{
			if (colour[wall] != TearsGame.NONE && spawnTick[wall] != UNKNOWN)
			{
				lastLife = tick - spawnTick[wall];
			}
			colour[wall] = TearsGame.NONE;
			spawnTick[wall] = UNKNOWN;
			return;
		}

		if (spawnsTick != tick)
		{
			spawnsTick = tick;
			spawnsThisTick.clear();
		}
		spawnsThisTick.add(wall);
		colour[wall] = newColour;

		if (spawnsThisTick.size() == 1)
		{
			spawnTick[wall] = tick;
			recordMove(tick, newColour);
		}
		else
		{
			// Several at once is the cave loading, not streams moving
			for (int w : spawnsThisTick)
			{
				spawnTick[w] = UNKNOWN;
			}
			if (!moves.isEmpty() && moves.peekLast()[0] == tick)
			{
				moves.pollLast();
			}
		}
	}

	private void recordMove(int tick, int moveColour)
	{
		if (!moves.isEmpty() && moves.peekLast()[0] != tick - 1)
		{
			moves.clear();
		}
		moves.add(new int[]{tick, moveColour});
		if (moves.size() == STREAMS)
		{
			StringBuilder sb = new StringBuilder();
			for (int[] move : moves)
			{
				sb.append(move[1] == TearsGame.BLUE ? 'b' : 'g');
			}
			order = sb.toString();
			moves.clear();
		}
	}

	/**
	 * @return the colours in the order this world moves its streams, such as "gggbbb", or null
	 * until a full cycle has been seen
	 */
	@Nullable
	String getOrder()
	{
		return order;
	}

	/**
	 * @return how many ticks the most recently departed stream stayed, or -1 if unknown
	 */
	int getLastLife()
	{
		return lastLife == UNKNOWN ? -1 : lastLife;
	}

	/**
	 * @return true once every stream's next move is known
	 */
	boolean isComplete()
	{
		int known = 0;
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			if (colour[wall] != TearsGame.NONE)
			{
				if (spawnTick[wall] == UNKNOWN)
				{
					return false;
				}
				known++;
			}
		}
		return known == STREAMS;
	}

	int colour(int wall)
	{
		return colour[wall];
	}

	/**
	 * @return the tick the stream on this wall next moves, or -1 if the wall is empty or unknown
	 */
	int nextMove(int wall)
	{
		return colour[wall] == TearsGame.NONE || spawnTick[wall] == UNKNOWN
			? -1
			: spawnTick[wall] + TearsGame.STREAM_LIFE;
	}

	/**
	 * Copies the streams into a game for planning. Only meaningful once {@link #isComplete()}.
	 */
	void fill(TearsGame game)
	{
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			game.colour[wall] = colour[wall];
			game.nextMove[wall] = nextMove(wall);
		}
	}
}

package com.togoptimizer;

import java.util.Random;

/**
 * A Tears of Guthix game that can be stepped forward a tick at a time, used to simulate what happens
 * after each choice.
 *
 * Mechanics, from the OSRS Wiki: three blue and three green streams occupy nine walls. Each stream
 * stays for 16 ticks, then moves to a random empty wall other than its own, keeping its colour. A
 * player collecting from a wall keeps collecting when it changes, gaining a tear per tick on blue
 * and losing one on green.
 */
final class TearsGame
{
	static final int NONE = 0;
	static final int BLUE = 1;
	static final int GREEN = -1;

	static final int STREAM_LIFE = 16;
	// Ticks between reaching a wall and the first tear. Measured in game: the first tear came the
	// distance plus two ticks after each click, and other players started collecting two ticks after
	// arriving.
	static final int START_DELAY = 2;

	/**
	 * Picks the wall to collect from next, or -1 to carry on as before.
	 */
	interface Policy
	{
		int choose(TearsGame game);
	}

	// Colour on each wall, which is also the tears it gives per tick
	final int[] colour = new int[Walls.COUNT];
	// Tick the stream on each wall moves on; unused for empty walls
	final int[] nextMove = new int[Walls.COUNT];

	int tick;
	int endTick;
	int x;
	int y;
	int target = -1;
	int readyTick;
	int pendingWall = -1;
	int pendingTick;
	int tears;
	// Ticks between the player choosing a wall and the click taking effect
	int reaction;
	Random rng;

	TearsGame copy(Random rng)
	{
		TearsGame game = new TearsGame();
		System.arraycopy(colour, 0, game.colour, 0, Walls.COUNT);
		System.arraycopy(nextMove, 0, game.nextMove, 0, Walls.COUNT);
		game.tick = tick;
		game.endTick = endTick;
		game.x = x;
		game.y = y;
		game.target = target;
		game.readyTick = readyTick;
		game.pendingWall = pendingWall;
		game.pendingTick = pendingTick;
		game.tears = tears;
		game.reaction = reaction;
		game.rng = rng;
		return game;
	}

	int remaining()
	{
		return endTick - tick;
	}

	boolean over()
	{
		return tick >= endTick;
	}

	void moveStreams()
	{
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			if (colour[wall] != NONE && nextMove[wall] == tick)
			{
				int destination = randomEmptyWall();
				colour[destination] = colour[wall];
				nextMove[destination] = tick + STREAM_LIFE;
				colour[wall] = NONE;
			}
		}
	}

	private int randomEmptyWall()
	{
		int empty = 0;
		for (int c : colour)
		{
			if (c == NONE)
			{
				empty++;
			}
		}
		int pick = rng.nextInt(empty);
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			if (colour[wall] == NONE && pick-- == 0)
			{
				return wall;
			}
		}
		throw new IllegalStateException("no empty wall");
	}

	/**
	 * Chooses a wall; the click lands after the reaction time. Ignored while another click is on its
	 * way, since the player is committed to it.
	 */
	void request(int wall)
	{
		if (wall < 0 || wall == target || pendingWall >= 0)
		{
			return;
		}
		pendingWall = wall;
		pendingTick = tick + reaction;
	}

	void step(Policy policy)
	{
		moveStreams();
		if (pendingWall < 0)
		{
			request(policy.choose(this));
		}
		finishTick();
	}

	/**
	 * The rest of a tick once streams have moved and the player has chosen.
	 */
	void finishTick()
	{
		if (pendingWall >= 0 && tick >= pendingTick)
		{
			goTo(pendingWall);
			pendingWall = -1;
		}
		if (target >= 0 && tick >= readyTick)
		{
			tears += colour[target];
		}
		tick++;
	}

	private void goTo(int wall)
	{
		if (wall == target)
		{
			return;
		}
		readyTick = tick + Walls.travel(x, y, wall) + START_DELAY;
		x = Walls.standX(wall);
		y = Walls.standY(wall);
		target = wall;
	}

	void runUntil(int stopTick, Policy policy)
	{
		int stop = Math.min(stopTick, endTick);
		while (tick < stop)
		{
			step(policy);
		}
	}

	/**
	 * When the current wall stops giving blue tears, go to the nearest blue one, preferring the one
	 * that lasts longer on a tie.
	 */
	static int nearestBlue(TearsGame game)
	{
		if (game.target >= 0 && game.colour[game.target] == BLUE)
		{
			return -1;
		}
		int best = -1;
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			if (game.colour[wall] != BLUE)
			{
				continue;
			}
			if (best < 0)
			{
				best = wall;
				continue;
			}
			int travel = Walls.travel(game.x, game.y, wall);
			int bestTravel = Walls.travel(game.x, game.y, best);
			if (travel < bestTravel || travel == bestTravel && game.nextMove[wall] > game.nextMove[best])
			{
				best = wall;
			}
		}
		return best;
	}
}

