@Slf4j
@PluginDescriptor(
	name = "Tears of Guthix Optimizer",
	description = "Highlights the best weeping wall, when to wait, and when to enter, with world order checks and a next-game countdown",
	tags = {"tog", "tears", "guthix", "tears of guthix", "weeping wall", "juna", "minigame"}
)
public class TogOptimizerPlugin extends Plugin
{
	static final int TOG_REGION = 12948;
	// Floor tiles in front of the walls, where the minigame is played
	private static final int ROOM_MIN_X = 3257;
	private static final int ROOM_MAX_X = 3260;
	private static final int ROOM_MIN_Y = 9515;
	private static final int ROOM_MAX_Y = 9519;
	// Where players appear when they enter the wall room, seen for everyone who entered while watched
	private static final int ENTRANCE_X = 3257;
	private static final int ENTRANCE_Y = 9517;
	static final int HORIZON = 40;
	private static final int ROLLOUTS = 200;
	// Ticks from a stream leaving to the player clicking; a real game measured one to three
	private static final int REACTION = 2;
	// How much lower another optimal world's ping must be to suggest hopping from an optimal world
	static final int FASTER_BY_MS = 10;
	private static final Set<WorldType> SUGGESTABLE = EnumSet.of(WorldType.MEMBERS, WorldType.LEGACY_ONLY, WorldType.EOC_ONLY);

	@Inject
	private Client client;

	@Inject
	private TogOptimizerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WallOverlay wallOverlay;

	@Inject
	private JunaOverlay junaOverlay;

	@Inject
	private ContinueOverlay continueOverlay;

	@Inject
	private WorldList worldList;

	@Inject
	private WorldService worldService;

	@Inject
	private WorldPinger pinger;

	@Inject
	private ConfigManager configManager;

	// Per-account records of when the next game unlocks and the experience when the last one ended
	private static final String UNLOCK_AT_KEY = "unlockAt";
	private static final String XP_AT_LAST_GAME_KEY = "xpAtLastGame";
	private int lastTears;
	// The reward experience lands as a game ends, so it's recorded a few ticks later
	private int recordXpTick = -1;
	private String lastDialogue = "";
	// Whether Juna's last line, the one that lets the player in, is on screen
	@Getter
	private boolean junasLastLine;

	// Juna's lines, worked out once a tick rather than every frame
	@Getter
	private List<Integer> suggestions = List.of();
	@Getter
	@Nullable
	private Integer fasterWorld;
	@Getter
	@Nullable
	private Long unlockAt;
	@Getter
	@Nullable
	private String requirement;

	@Getter
	private final StreamTracker tracker = new StreamTracker();
	private final Planner planner = new Planner(ROLLOUTS, HORIZON);

	// The latest estimate for the player, or for the preview player while outside the wall room
	@Getter
	@Nullable
	private Planner.Plan plan;
	@Nullable
	private PreviewRun preview;
	// The wall to highlight, which only changes when another is clearly better
	@Getter
	private int shownBest = -1;

	// The wall the player last chose to collect from, or -1
	private int collectingWall = -1;
	// The tick the player stepped into the wall room, when their time started, or -1
	private int gameStartTick = -1;

	// The stream object currently showing on each wall, for outlining
	private final DecorativeObject[] wallObjects = new DecorativeObject[Walls.COUNT];
	// The permanent weeping wall behind each stream, whose clickable area marks an empty wall to wait at
	private final TileObject[] baseWalls = new TileObject[Walls.COUNT];
	// Ticks left to wait for a blue to land on the player's empty wall, or -1 if not waiting
	@Getter
	private int waitTicks = -1;

	// Juna is scenery rather than an NPC
	@Getter
	@Nullable
	private GameObject juna;

	@Provides
	TogOptimizerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TogOptimizerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(wallOverlay);
		overlayManager.add(junaOverlay);
		overlayManager.add(continueOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(wallOverlay);
		overlayManager.remove(junaOverlay);
		overlayManager.remove(continueOverlay);
		tracker.reset();
		Arrays.fill(wallObjects, null);
		Arrays.fill(baseWalls, null);
		worldList.clear();
		pinger.shutDown();
		preview = null;
		plan = null;
		shownBest = -1;
		waitTicks = -1;
		collectingWall = -1;
		juna = null;
		suggestions = List.of();
		fasterWorld = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!TogOptimizerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (!config.fetchWorldList())
		{
			worldList.clear();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			// The streams are sent again after a load, with no way to tell how long they have left
			tracker.reset();
			preview = null;
			if (state == GameState.LOGIN_SCREEN)
			{
				// Pings are kept for the whole login, as the player can't have moved until they log out
				pinger.clear();
			}
			Arrays.fill(wallObjects, null);
			Arrays.fill(baseWalls, null);
			plan = null;
			shownBest = -1;
			waitTicks = -1;
			collectingWall = -1;
			gameStartTick = -1;
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (event.getGameObject().getId() == ObjectID.TOG_JUNA)
		{
			juna = event.getGameObject();
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (event.getGameObject() == juna)
		{
			juna = null;
		}
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		baseWall(event.getWallObject(), true);
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		baseWall(event.getWallObject(), false);
	}

	private void baseWall(TileObject object, boolean spawned)
	{
		if (object.getId() != ObjectID.TOG_WEEPINGWALL)
		{
			return;
		}
		int wall = Walls.at(object.getWorldLocation().getX(), object.getWorldLocation().getY());
		if (wall < 0)
		{
			return;
		}
		if (spawned)
		{
			baseWalls[wall] = object;
		}
		else if (baseWalls[wall] == object)
		{
			baseWalls[wall] = null;
		}
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		wallObject(event.getDecorativeObject(), true);
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		wallObject(event.getDecorativeObject(), false);
	}

	private void wallObject(DecorativeObject object, boolean spawned)
	{
		int colour = colourOf(object.getId());
		if (colour == Integer.MIN_VALUE)
		{
			return;
		}
		WorldPoint location = object.getWorldLocation();
		int wall = Walls.at(location.getX(), location.getY());
		if (wall < 0)
		{
			return;
		}

		int tick = client.getTickCount();
		if (spawned)
		{
			wallObjects[wall] = object;
			tracker.wallChanged(wall, colour, tick);
		}
		if (!spawned && wallObjects[wall] == object)
		{
			wallObjects[wall] = null;
		}
		if (!spawned && colour != TearsGame.NONE && tracker.colour(wall) == colour)
		{
			// A stream's object leaving, in case the empty wall isn't sent as its own object
			tracker.wallChanged(wall, TearsGame.NONE, tick);
		}

		if (config.debugLogging())
		{
			log.info("togoptimizer wall tick={} wall={} object={} {} colour={} lastLife={} order={} complete={}",
				tick, wall, object.getId(), spawned ? "spawned" : "despawned", colour, tracker.getLastLife(),
				tracker.getOrder(), tracker.isComplete());
		}
	}

	/**
	 * @return the colour a weeping wall object shows, or MIN_VALUE if it isn't one
	 */
	private static int colourOf(int objectId)
	{
		switch (objectId)
		{
			case ObjectID.TOG_WEEPING_WALL_GOOD_R:
			case ObjectID.TOG_WEEPING_WALL_GOOD_L:
				return TearsGame.BLUE;
			case ObjectID.TOG_WEEPING_WALL_BAD_R:
			case ObjectID.TOG_WEEPING_WALL_BAD_L:
				return TearsGame.GREEN;
			case ObjectID.TOG_WEEPING_WALL_OFF_R:
			case ObjectID.TOG_WEEPING_WALL_OFF_L:
				return TearsGame.NONE;
			default:
				return Integer.MIN_VALUE;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!inCave())
		{
			return;
		}
		int wall = -1;
		if ("Collect-from".equals(event.getMenuOption()))
		{
			WorldPoint point = WorldPoint.fromScene(client.getTopLevelWorldView(), event.getParam0(), event.getParam1(),
				client.getTopLevelWorldView().getPlane());
			wall = Walls.at(point.getX(), point.getY());
		}
		// Any other click walks the player away from the wall
		collectingWall = wall;

		if (config.debugLogging())
		{
			log.info("togoptimizer click tick={} option={} target={} id={} wall={}", client.getTickCount(),
				event.getMenuOption(), event.getMenuTarget(), event.getId(), wall);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.TOG_TEARS_COLLECTED)
		{
			// The count resets when the game ends and the reward is given
			if (event.getValue() == 0 && lastTears > 0)
			{
				gameEnded();
			}
			lastTears = event.getValue();
		}

		// The minigame's own state: whether the player is collecting, their tears, and the quest points needed
		if (config.debugLogging() && isTogVariable(event))
		{
			log.info("togoptimizer var tick={} varbit={} varp={} value={}", client.getTickCount(), event.getVarbitId(),
				event.getVarpId(), event.getValue());
		}
	}

	private static boolean isTogVariable(VarbitChanged event)
	{
		int varbit = event.getVarbitId();
		return varbit >= VarbitID.TOG_JUNA_BOWL && varbit <= VarbitID.TOG_QP_BEFORE_RETURN
			|| event.getVarpId() == VarPlayerID.TOG_MINIGAME;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (recordXpTick >= 0 && client.getTickCount() >= recordXpTick)
		{
			recordXpTick = -1;
			configManager.setRSProfileConfiguration(TogOptimizerConfig.GROUP, XP_AT_LAST_GAME_KEY, client.getOverallExperience());
		}


		if (!inCave())
		{
			plan = null;
			shownBest = -1;
			waitTicks = -1;
			preview = null;
			return;
		}

		readDialogue();
		updateJunaLines();

		// Only contact the third-party site at Tears of Guthix itself: Juna only exists in its cave, while
		// the map region also covers part of the Lumbridge Swamp Caves
		if (config.fetchWorldList() && juna != null)
		{
			worldList.refreshIfStale();
		}

		int tick = client.getTickCount();
		if (!tracker.isComplete())
		{
			plan = null;
			shownBest = -1;
			waitTicks = -1;
			return;
		}

		Player player = client.getLocalPlayer();
		WorldPoint location = player.getWorldLocation();
		// Nothing on the walls to plan for
		boolean shown = config.highlightBest() || config.showExpected();
		if (!inRoom(location))
		{
			gameStartTick = -1;
			if (config.onlyInRoom() || !shown)
			{
				preview = null;
				plan = null;
				shownBest = -1;
				waitTicks = -1;
			}
			else
			{
				previewTick(tick);
			}
			return;
		}
		preview = null;
		int questPoints = client.getVarpValue(VarPlayerID.QP);
		if (gameStartTick < 0)
		{
			gameStartTick = tick;
			if (config.debugLogging())
			{
				log.info("togoptimizer game start tick={} questPoints={}", tick, questPoints);
			}
		}
		if (!shown)
		{
			plan = null;
			shownBest = -1;
			waitTicks = -1;
			return;
		}

		TearsGame game = new TearsGame();
		tracker.fill(game);
		game.tick = tick;
		// The minigame gives one tick per quest point
		game.endTick = gameStartTick + questPoints;
		game.x = location.getX();
		game.y = location.getY();
		game.target = collectingWall;
		game.reaction = REACTION;
		boolean atWall = collectingWall >= 0 && game.x == Walls.standX(collectingWall) && game.y == Walls.standY(collectingWall);
		game.readyTick = atWall || collectingWall < 0 ? tick : tick + Walls.travel(game.x, game.y, collectingWall) + TearsGame.START_DELAY;

		// The same futures every tick, so the estimates don't jitter from one tick to the next
		plan = planner.plan(game, 0);
		shownBest = Planner.steady(shownBest, plan, Planner.STEADY_MARGIN);
		waitTicks = Planner.waitTicksFor(game, shownBest);

		if (config.debugLogging())
		{
			log.info("togoptimizer player tick={} at={},{} collecting={} tears={} best={} expected={}", tick, game.x,
				game.y, collectingWall, client.getVarbitValue(VarbitID.TOG_TEARS_COLLECTED), plan.getBest(),
				describe(plan));
		}
	}

	private void updateJunaLines()
	{
		unlockAt = readUnlockAt();
		requirement = readRequirement();
		boolean online = config.fetchWorldList() && juna != null;
		boolean optimal = StreamTracker.OPTIMAL_ORDER.equals(worldOrder());
		suggestions = online && !optimal ? suggestedWorlds() : List.of();
		fasterWorld = online && optimal ? findFasterWorld() : null;
	}

	private void previewTick(int tick)
	{
		if (preview == null || preview.isOver())
		{
			int questPoints = client.getVarpValue(VarPlayerID.QP);
			preview = new PreviewRun(tick, Math.max(questPoints, HORIZON), ENTRANCE_X, ENTRANCE_Y, REACTION, planner, tick);
		}
		preview.tick(tracker, tick);
		plan = preview.getPlan();
		shownBest = preview.getShown();
		waitTicks = preview.getWaitTicks();
	}

	private void gameEnded()
	{
		long now = System.currentTimeMillis();
		configManager.setRSProfileConfiguration(TogOptimizerConfig.GROUP, UNLOCK_AT_KEY, Eligibility.unlockAfterGame(now));
		recordXpTick = client.getTickCount() + 3;
		if (config.debugLogging())
		{
			log.info("togoptimizer game ended tick={} unlockAt={}", client.getTickCount(), Eligibility.unlockAfterGame(now));
		}
	}

	/**
	 * Watches dialogue for Juna saying how many days until the player can play again.
	 */
	private void readDialogue()
	{
		String text = dialogueText(InterfaceID.ChatLeft.TEXT);
		if (text == null)
		{
			text = dialogueText(InterfaceID.Messagebox.TEXT);
		}
		if (text == null)
		{
			text = dialogueText(InterfaceID.Objectbox.TEXT);
		}
		junasLastLine = text != null && text.contains(EntryTiming.LAST_LINE);
		if (text == null || text.equals(lastDialogue))
		{
			return;
		}
		lastDialogue = text;
		if (config.debugLogging())
		{
			log.info("togoptimizer dialogue tick={} text={}", client.getTickCount(), text);
		}
		Integer days = Eligibility.daysFromJuna(text);
		if (days != null)
		{
			configManager.setRSProfileConfiguration(TogOptimizerConfig.GROUP, UNLOCK_AT_KEY,
				Eligibility.unlockInDays(days, System.currentTimeMillis()));
		}
	}

	@Nullable
	private String dialogueText(int widgetId)
	{
		Widget widget = client.getWidget(widgetId);
		if (widget == null || widget.isHidden() || widget.getText() == null)
		{
			return null;
		}
		return Text.removeTags(widget.getText().replace("<br>", " "));
	}

	/**
	 * @return when this account can next play, or null if unknown or already possible
	 */
	@Nullable
	private Long readUnlockAt()
	{
		Long unlock = configManager.getRSProfileConfiguration(TogOptimizerConfig.GROUP, UNLOCK_AT_KEY, Long.class);
		return unlock == null || unlock <= System.currentTimeMillis() ? null : unlock;
	}

	/**
	 * @return the quest point or experience still needed to play again, or null if met
	 */
	@Nullable
	private String readRequirement()
	{
		Long xpAtLastGame = configManager.getRSProfileConfiguration(TogOptimizerConfig.GROUP, XP_AT_LAST_GAME_KEY, Long.class);
		return Eligibility.requirement(client.getVarbitValue(VarbitID.TOG_QP_BEFORE_RETURN),
			client.getVarpValue(VarPlayerID.QP), client.getOverallExperience(), xpAtLastGame);
	}

	private static String describe(@Nullable Planner.Plan plan)
	{
		if (plan == null)
		{
			return "-";
		}
		StringBuilder sb = new StringBuilder();
		double[] expected = plan.getExpected();
		for (int wall = 0; wall < expected.length; wall++)
		{
			if (!Double.isNaN(expected[wall]))
			{
				sb.append(wall).append('=').append(String.format("%.1f", expected[wall])).append(' ');
			}
		}
		return sb.toString().trim();
	}

	@Nullable
	DecorativeObject wallObject(int wall)
	{
		return wallObjects[wall];
	}

	@Nullable
	TileObject baseWall(int wall)
	{
		return baseWalls[wall];
	}

	boolean inCave()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return false;
		}
		return client.getLocalPlayer().getWorldLocation().getRegionID() == TOG_REGION;
	}

	int currentWorld()
	{
		return client.getWorld();
	}

	boolean playerInRoom()
	{
		return client.getLocalPlayer() != null && inRoom(client.getLocalPlayer().getWorldLocation());
	}

	/**
	 * Only the blue streams' timings are needed, so after a hop this is known as soon as the blues have
	 * each moved once, sooner than the full stream order.
	 *
	 * @return 0 if now is a good time to continue past Juna's last line, the ticks to wait otherwise, or
	 * -1 if unknown
	 */
	int ticksUntilContinue()
	{
		if (!StreamTracker.OPTIMAL_ORDER.equals(worldOrder()))
		{
			return -1;
		}
		int[] colour = new int[Walls.COUNT];
		int[] nextMove = new int[Walls.COUNT];
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			colour[wall] = tracker.colour(wall);
			nextMove[wall] = tracker.nextMove(wall);
			if (colour[wall] == TearsGame.BLUE && nextMove[wall] < 0)
			{
				return -1;
			}
		}
		int firstBlue = EntryTiming.firstBlueMove(colour, nextMove);
		return firstBlue < 0 ? -1 : EntryTiming.ticksUntilContinue(firstBlue, client.getTickCount());
	}

	@Nullable
	Integer pingOf(int world)
	{
		return pinger.pingOf(world);
	}

	/**
	 * On an optimal world, another optimal world with a clearly lower ping, as a lower ping makes clicks
	 * land on the intended tick more often.
	 *
	 * @return that world, or null if there's none or the pings aren't measured yet
	 */
	@Nullable
	private Integer findFasterWorld()
	{
		WorldResult worlds = worldService.getWorlds();
		World current = worlds == null ? null : worlds.findWorld(client.getWorld());
		if (current == null)
		{
			return null;
		}
		pinger.pingOnce(current.getId(), current.getAddress());
		List<Integer> candidates = suggestedWorlds();
		if (candidates.isEmpty())
		{
			return null;
		}
		int best = candidates.get(0);
		return WorldPinger.isFaster(pinger.pingOf(best), pinger.pingOf(current.getId()), FASTER_BY_MS) ? best : null;
	}

	private static boolean inRoom(WorldPoint location)
	{
		return location.getX() >= ROOM_MIN_X && location.getX() <= ROOM_MAX_X
			&& location.getY() >= ROOM_MIN_Y && location.getY() <= ROOM_MAX_Y;
	}

	/**
	 * @return this world's stream order, from the streams if they've been watched for a cycle,
	 * otherwise from the online list, or null
	 */
	@Nullable
	String worldOrder()
	{
		String seen = tracker.getOrder();
		if (seen != null)
		{
			return seen;
		}
		return config.fetchWorldList() ? worldList.orderOf(client.getWorld()) : null;
	}

	/**
	 * @return up to three optimal worlds to hop to, nearest first once measured, if the online list is on
	 */
	private List<Integer> suggestedWorlds()
	{
		WorldResult worlds = worldService.getWorlds();
		if (worlds == null)
		{
			return List.of();
		}
		int current = client.getWorld();
		List<Integer> candidates = worldList.optimalWorlds(Integer.MAX_VALUE, id ->
		{
			World world = worlds.findWorld(id);
			return id != current && world != null && world.getTypes().contains(WorldType.MEMBERS)
				&& SUGGESTABLE.containsAll(world.getTypes());
		});
		for (int id : candidates)
		{
			pinger.pingOnce(id, worlds.findWorld(id).getAddress());
		}
		return WorldPinger.byPing(candidates, pinger::pingOf, 3);
	}
}

package com.togoptimizer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.TileObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Expected tears at the best wall, and optionally an outline around it.
 */
class WallOverlay extends Overlay
{
	private static final int TEXT_HEIGHT = 120;
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 4;

	private final Client client;
	private final TogOptimizerPlugin plugin;
	private final TogOptimizerConfig config;
	private final ModelOutlineRenderer outlines;

	@Inject
	private WallOverlay(Client client, TogOptimizerPlugin plugin, TogOptimizerConfig config, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Planner.Plan plan = plugin.getPlan();
		int shown = plugin.getShownBest();
		if (plan == null || shown < 0)
		{
			return null;
		}

		int waitTicks = plugin.getWaitTicks();
		if (waitTicks >= 0)
		{
			return renderWait(graphics, shown, waitTicks);
		}

		if (config.highlightBest())
		{
			DecorativeObject wall = plugin.wallObject(shown);
			if (wall != null)
			{
				outlines.drawOutline(wall, OUTLINE_WIDTH, config.highlightColour(), OUTLINE_FEATHER);
			}
		}

		if (!config.showExpected())
		{
			return null;
		}
		drawText(graphics, shown, String.format("%.1f", plan.getExpected()[shown]), config.highlightColour());
		return null;
	}

	/**
	 * Staying put for a blue to land: the empty wall in the wait colour, and how many ticks are left
	 * before giving up. The countdown shows even without numbers, as it's the only sign the plugin is
	 * saying to wait.
	 */
	private Dimension renderWait(Graphics2D graphics, int shown, int waitTicks)
	{
		if (!config.highlightBest() && !config.showExpected())
		{
			return null;
		}
		if (config.highlightBest())
		{
			// Neither an empty wall's stream object (no faces) nor the weeping wall (an invisible flat panel)
			// has a visible model to outline, so the weeping wall's clickable area over the crack is drawn
			TileObject wall = plugin.baseWall(shown);
			Shape area = wall == null ? null : wall.getClickbox();
			if (area != null)
			{
				OverlayUtil.renderPolygon(graphics, area, config.waitColour());
			}
		}
		drawText(graphics, shown, waitTicks > 0 ? "Wait " + waitTicks : "Wait", config.waitColour());
		return null;
	}

	private void drawText(Graphics2D graphics, int shown, String text, Color colour)
	{
		LocalPoint point = LocalPoint.fromWorld(client.getTopLevelWorldView(), Walls.wallX(shown), Walls.wallY(shown));
		if (point == null)
		{
			return;
		}
		Point location = Perspective.getCanvasTextLocation(client, graphics, point, text, TEXT_HEIGHT);
		if (location != null)
		{
			OverlayUtil.renderTextLocation(graphics, location, text, colour);
		}
	}
}

package com.togoptimizer;

/**
 * The nine weeping walls in the Tears of Guthix cave, indexed south wall (west to east), east wall
 * (south to north), then north wall (west to east).
 */
final class Walls
{
	static final int COUNT = 9;

	// Wall tiles from the OSRS Wiki's weeping wall map
	private static final int[][] WALL = {
		{3257, 9514}, {3258, 9514}, {3259, 9514},
		{3261, 9516}, {3261, 9517}, {3261, 9518},
		{3257, 9520}, {3258, 9520}, {3259, 9520},
	};

	// The floor tile in front of each wall, where the player stands to collect
	private static final int[][] STAND = {
		{3257, 9515}, {3258, 9515}, {3259, 9515},
		{3260, 9516}, {3260, 9517}, {3260, 9518},
		{3257, 9519}, {3258, 9519}, {3259, 9519},
	};

	private Walls()
	{
	}

	/**
	 * @return the wall at this tile, or -1 if it isn't one
	 */
	static int at(int x, int y)
	{
		for (int i = 0; i < COUNT; i++)
		{
			if (WALL[i][0] == x && WALL[i][1] == y)
			{
				return i;
			}
		}
		return -1;
	}

	static int wallX(int wall)
	{
		return WALL[wall][0];
	}

	static int wallY(int wall)
	{
		return WALL[wall][1];
	}

	static int standX(int wall)
	{
		return STAND[wall][0];
	}

	static int standY(int wall)
	{
		return STAND[wall][1];
	}

	/**
	 * Ticks to get from a tile to a wall's standing tile across the open cave floor. Everyone walks in
	 * the minigame, one tile a tick, even with run on.
	 */
	static int travel(int x, int y, int wall)
	{
		return Math.max(Math.abs(x - standX(wall)), Math.abs(y - standY(wall)));
	}
}

package com.togoptimizer;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntPredicate;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Stream orders reported by ToG Crowdsourcing users. Read only: this plugin never submits anything.
 */
@Slf4j
@Singleton
class WorldList
{
	private static final String URL = "https://togcrowdsourcing.com/worldinfo";
	private static final long REFRESH_MS = 10 * 60 * 1000;

	static class Entry
	{
		@SerializedName("world_number")
		int world;
		@SerializedName("stream_order")
		String order;
		int hits;
	}

	private final OkHttpClient http;
	private final Gson gson;

	private volatile Map<Integer, Entry> worlds = Collections.emptyMap();
	private long lastRequest;

	@Inject
	WorldList(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/**
	 * Fetches the list unless it was requested recently.
	 */
	void refreshIfStale()
	{
		long now = System.currentTimeMillis();
		if (now - lastRequest < REFRESH_MS)
		{
			return;
		}
		lastRequest = now;

		Request request = new Request.Builder().url(URL).build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Couldn't fetch the ToG world list", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						log.debug("ToG world list request failed: {}", response.code());
						return;
					}
					worlds = parse(gson, body.string());
				}
				catch (IOException | JsonParseException e)
				{
					log.debug("Couldn't read the ToG world list", e);
				}
			}
		});
	}

	static Map<Integer, Entry> parse(Gson gson, String json)
	{
		Entry[] entries = gson.fromJson(json, Entry[].class);
		Map<Integer, Entry> byWorld = new HashMap<>();
		if (entries != null)
		{
			for (Entry entry : entries)
			{
				if (entry != null && entry.order != null)
				{
					byWorld.put(entry.world, entry);
				}
			}
		}
		return byWorld;
	}

	void clear()
	{
		worlds = Collections.emptyMap();
		lastRequest = 0;
	}

	@Nullable
	String orderOf(int world)
	{
		Entry entry = worlds.get(world);
		return entry == null ? null : entry.order;
	}

	/**
	 * @return up to {@code limit} optimal worlds, most reported first
	 */
	List<Integer> optimalWorlds(int limit, IntPredicate usable)
	{
		return optimalWorlds(worlds, limit, usable);
	}

	static List<Integer> optimalWorlds(Map<Integer, Entry> worlds, int limit, IntPredicate usable)
	{
		List<Entry> optimal = new ArrayList<>();
		for (Entry entry : worlds.values())
		{
			if (StreamTracker.OPTIMAL_ORDER.equals(entry.order) && usable.test(entry.world))
			{
				optimal.add(entry);
			}
		}
		optimal.sort(Comparator.comparingInt((Entry e) -> e.hits).reversed());

		List<Integer> result = new ArrayList<>();
		for (int i = 0; i < Math.min(limit, optimal.size()); i++)
		{
			result.add(optimal.get(i).world);
		}
		return result;
	}
}

package com.togoptimizer;

import java.io.IOException;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.IntFunction;
import javax.annotation.Nullable;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Measures how long it takes to reach worlds, so suggestions favour ones near the player. Each world
 * is measured once per login, since the player's location doesn't change while logged in. Only Jagex's
 * game servers are contacted.
 */
@Slf4j
@Singleton
class WorldPinger
{
	private static final int GAME_PORT = 43594;
	private static final int TIMEOUT_MS = 2000;

	private final Map<Integer, Integer> pings = new ConcurrentHashMap<>();
	private final Set<Integer> requested = ConcurrentHashMap.newKeySet();
	@Nullable
	private ExecutorService executor;

	/**
	 * Measures a world in the background, unless it has been already this login.
	 */
	synchronized void pingOnce(int world, String address)
	{
		if (!requested.add(world))
		{
			return;
		}
		if (executor == null)
		{
			executor = Executors.newSingleThreadExecutor();
		}
		executor.execute(() ->
		{
			int ms = ping(address);
			if (ms >= 0)
			{
				pings.put(world, ms);
			}
		});
	}

	/**
	 * @return milliseconds to open a connection to the world, or -1 if it couldn't be reached
	 */
	private static int ping(String address)
	{
		try
		{
			// Resolved first so the lookup isn't counted
			InetAddress host = InetAddress.getByName(address);
			long start = System.nanoTime();
			try (Socket socket = new Socket())
			{
				socket.connect(new InetSocketAddress(host, GAME_PORT), TIMEOUT_MS);
			}
			return (int) ((System.nanoTime() - start) / 1_000_000);
		}
		catch (IOException e)
		{
			log.debug("Couldn't reach world {}", address, e);
			return -1;
		}
	}

	@Nullable
	Integer pingOf(int world)
	{
		return pings.get(world);
	}

	/**
	 * Forgets all measurements, for a new login that may be from somewhere else.
	 */
	void clear()
	{
		pings.clear();
		requested.clear();
	}

	synchronized void shutDown()
	{
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
		clear();
	}

	/**
	 * @return true if both pings are known and the candidate's is lower by at least {@code by} ms
	 */
	static boolean isFaster(@Nullable Integer candidate, @Nullable Integer current, int by)
	{
		return candidate != null && current != null && candidate <= current - by;
	}

	/**
	 * Orders candidate worlds by ping, fastest first. Worlds not measured yet keep their original
	 * order after the measured ones.
	 */
	static List<Integer> byPing(List<Integer> candidates, IntFunction<Integer> ping, int limit)
	{
		List<Integer> measured = new ArrayList<>();
		List<Integer> unmeasured = new ArrayList<>();
		for (int world : candidates)
		{
			(ping.apply(world) != null ? measured : unmeasured).add(world);
		}
		measured.sort(Comparator.comparingInt(ping::apply));
		measured.addAll(unmeasured);
		return measured.subList(0, Math.min(limit, measured.size()));
	}
}

package com.togoptimizer;

import java.time.Instant;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class EligibilityTest
{
	private static long at(String instant)
	{
		return Instant.parse(instant).toEpochMilli();
	}

	@Test
	public void aGameUnlocksTheNextAtTheStartOfTheSeventhDay()
	{
		assertEquals(at("2026-10-04T00:00:00Z"), Eligibility.unlockAfterGame(at("2026-09-27T13:18:23Z")));
		// A game just before the daily reset still counts from its own day
		assertEquals(at("2026-10-04T00:00:00Z"), Eligibility.unlockAfterGame(at("2026-09-27T23:59:00Z")));
	}

	@Test
	public void junasDaysCountFromTodaysReset()
	{
		assertEquals(at("2026-10-04T00:00:00Z"), Eligibility.unlockInDays(7, at("2026-09-27T18:10:00Z")));
	}

	@Test
	public void readsJunasReply()
	{
		// Both of her replies, as seen in game
		assertEquals(Integer.valueOf(7), Eligibility.daysFromJuna("Your stories have entertained me. But I will not permit any "
			+ "adventurer to access the tears more than once a week. Come back in 7 days."));
		assertEquals(Integer.valueOf(7), Eligibility.daysFromJuna("It has not been long since your last visit. Come again in 7 days."));
		assertEquals(Integer.valueOf(1), Eligibility.daysFromJuna("Come back in 1 day."));
		assertEquals(Integer.valueOf(1), Eligibility.daysFromJuna("Come back tomorrow."));
		assertNull(Eligibility.daysFromJuna("Tell me a story and I will let you into the cave."));
	}

	@Test
	public void formatsTimeLeft()
	{
		long minute = 60_000;
		assertEquals("6d 9h 55m", Eligibility.formatRemaining(((6 * 24 + 9) * 60 + 55) * minute));
		assertEquals("2h 0m", Eligibility.formatRemaining(120 * minute));
		assertEquals("1m", Eligibility.formatRemaining(1_000));
	}

	@Test
	public void describesWhatsStillNeeded()
	{
		// Quest points already met, or no requirement recorded
		assertNull(Eligibility.requirement(323, 323, 0, null));
		assertNull(Eligibility.requirement(0, 5, 0, null));
		// Experience gained since the last game counts instead
		assertEquals("Needs 1 more quest point or 38,500 XP", Eligibility.requirement(323, 322, 1_061_500, 1_000_000L));
		assertNull(Eligibility.requirement(323, 322, 1_100_000, 1_000_000L));
		// Without a record of the last game's experience
		assertEquals("Needs 2 more quest points or 100,000 XP since your last game", Eligibility.requirement(324, 322, 0, null));
	}
