package com.togoptimizer;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class EntryTimingTest
{
	private static final int N = TearsGame.NONE;
	private static final int B = TearsGame.BLUE;
	private static final int G = TearsGame.GREEN;

	@Test
	public void findsTheFirstBlueOfTheCycle()
	{
		// Blues move on ticks 110, 111 and 112; greens earlier
		int[] colour = {B, G, B, N, G, B, N, G, N};
		int[] nextMove = {111, 107, 110, -1, 108, 112, -1, 109, -1};

		assertEquals(110, EntryTiming.firstBlueMove(colour, nextMove));
	}

	@Test
	public void findsItMidBurst()
	{
		// The first blue moved on tick 100 and is next due on 116; the other two move on 101 and 102
		int[] colour = {B, G, B, N, G, B, N, G, N};
		int[] nextMove = {116, 113, 101, -1, 114, 102, -1, 115, -1};

		assertEquals(116, EntryTiming.firstBlueMove(colour, nextMove));
	}

	@Test
	public void onlyTheBluesNeedToBeKnown()
	{
		// Just after a hop: the blues have been seen moving, the greens not yet
		int[] colour = {B, G, B, N, G, B, N, G, N};
		int[] nextMove = {111, -1, 110, -1, -1, 112, -1, -1, -1};

		assertEquals(110, EntryTiming.firstBlueMove(colour, nextMove));
	}

	@Test
	public void theBestMomentLeavesTheFirstBlueMovingJustAfterEntering()
	{
		// Continuing on tick 112 starts the game on 115, one tick before the first blue moves on 116
		assertEquals(0, EntryTiming.ticksUntilContinue(116, 112));
		// Entering from two ticks before it moves to one tick after is still good
		assertEquals(0, EntryTiming.ticksUntilContinue(116, 111));
		assertEquals(0, EntryTiming.ticksUntilContinue(116, 113));
		assertEquals(0, EntryTiming.ticksUntilContinue(116, 114));
		// Too late for this cycle: the next good moment is tick 127, for the move on 132
		assertEquals(12, EntryTiming.ticksUntilContinue(116, 115));
		// Early: count down to the window opening on tick 111
		assertEquals(3, EntryTiming.ticksUntilContinue(116, 108));
	}
}

package com.togoptimizer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PlannerTest
{
	@Test
	public void onlyBlueWallsAndWaitingAreOptions()
	{
		TearsGame game = TearsGameTest.game("gggbbb", 300, 1, 5);
		game.moveStreams();
		Planner.Plan plan = new Planner(50, 40).plan(game, 1);

		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			// The player hasn't picked a wall yet, so there's nowhere to wait
			boolean option = game.colour[wall] == TearsGame.BLUE;
			assertEquals("wall " + wall, option, !Double.isNaN(plan.getExpected()[wall]));
		}
		assertEquals(TearsGame.BLUE, game.colour[plan.getBest()]);
	}

	@Test
	public void waitingAtAnEmptyWallIsAnOption()
	{
		TearsGame game = TearsGameTest.game("gggbbb", 300, 1, 5);
		game.moveStreams();
		int empty = 0;
		while (game.colour[empty] != TearsGame.NONE)
		{
			empty++;
		}
		game.target = empty;

		Planner.Plan plan = new Planner(50, 40).plan(game, 1);

		assertTrue(!Double.isNaN(plan.getExpected()[empty]));
	}

	@Test
	public void optionsStillDifferWhileAClickIsOnItsWay()
	{
		// A click already on its way used to lock every option into the same future
		TearsGame game = TearsGameTest.game("gggbbb", 300, 1, 5);
		game.moveStreams();
		int firstBlue = 0;
		while (game.colour[firstBlue] != TearsGame.BLUE)
		{
			firstBlue++;
		}
		game.request(firstBlue);

		double[] expected = new Planner(100, 40).plan(game, 1).getExpected();

		double min = Double.MAX_VALUE;
		double max = -Double.MAX_VALUE;
		for (double e : expected)
		{
			if (!Double.isNaN(e))
			{
				min = Math.min(min, e);
				max = Math.max(max, e);
			}
		}
		assertTrue(max - min > 0.1);
	}

	private static Planner.Plan plan(double... expected)
	{
		int best = -1;
		for (int i = 0; i < expected.length; i++)
		{
			if (!Double.isNaN(expected[i]) && (best < 0 || expected[i] > expected[best]))
			{
				best = i;
			}
		}
		return new Planner.Plan(expected, best);
	}

	@Test
	public void theShownChoiceHoldsThroughNearTies()
	{
		double n = Double.NaN;
		assertEquals(2, Planner.steady(2, plan(n, 30.4, 30.1, n), 0.5));
		// Clearly beaten
		assertEquals(1, Planner.steady(2, plan(n, 31.0, 30.1, n), 0.5));
		// No longer an option
		assertEquals(1, Planner.steady(3, plan(n, 30.4, 30.1, n), 0.5));
		// Nothing shown yet
		assertEquals(1, Planner.steady(-1, plan(n, 30.4, 30.1, n), 0.5));
	}

	@Test
	public void waitingLastsUntilTheBurstsLastBlueMoves()
	{
		TearsGame game = new TearsGame();
		game.tick = 100;
		game.colour[0] = TearsGame.BLUE;
		game.nextMove[0] = 101;
		game.colour[1] = TearsGame.BLUE;
		game.nextMove[1] = 102;
		// Moved on this tick, so it isn't due again for a whole cycle
		game.colour[2] = TearsGame.BLUE;
		game.nextMove[2] = 116;

		assertEquals(2, Planner.waitTicks(game));

		game.tick = 102;
		game.nextMove[0] = 117;
		game.nextMove[1] = 118;
		assertEquals(-1, Planner.waitTicks(game));
	}

	@Test
	public void waitingIsOnlyOfferedWhileABlueCanStillLand()
	{
		TearsGame game = new TearsGame();
		game.tick = 100;
		game.endTick = 400;
		game.x = Walls.standX(4);
		game.y = Walls.standY(4);
		game.target = 4;
		game.reaction = 2;
		game.rng = new java.util.Random(1);
		int[] blues = {0, 2, 7};
		int[] greens = {1, 5, 8};
		for (int i = 0; i < 3; i++)
		{
			game.colour[blues[i]] = TearsGame.BLUE;
			game.colour[greens[i]] = TearsGame.GREEN;
			game.nextMove[greens[i]] = 110 + i;
		}
		// Every blue has just moved, so none can land on wall 4 for over ten ticks
		game.nextMove[0] = 114;
		game.nextMove[2] = 115;
		game.nextMove[7] = 116;
		assertTrue(Double.isNaN(new Planner(50, 40).plan(game, 1).getExpected()[4]));
		assertEquals(-1, Planner.waitTicksFor(game, 4));

		// Two blues still to move this burst: waiting is an option, for two more ticks
		game.nextMove[2] = 101;
		game.nextMove[7] = 102;
		assertTrue(!Double.isNaN(new Planner(50, 40).plan(game, 1).getExpected()[4]));
		assertEquals(2, Planner.waitTicksFor(game, 4));
	}

	@Test
	public void beatsGoingToTheNearestBlue()
	{
		// Simulations put the planner well ahead of going to the nearest blue
		int games = 30;
		double planned = 0;
		double nearest = 0;
		Planner planner = new Planner(100, 40);
		for (int seed = 0; seed < games; seed++)
		{
			TearsGame a = TearsGameTest.game("gggbbb", 300, 1, seed);
			a.runUntil(300, planner.asPolicy(seed));
			planned += a.tears;

			TearsGame b = TearsGameTest.game("gggbbb", 300, 1, seed);
			b.runUntil(300, TearsGame::nearestBlue);
			nearest += b.tears;
		}
		double gain = (planned - nearest) / games;
		assertTrue("gain was " + gain, gain > 3);
	}
}

package com.togoptimizer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PreviewRunTest
{
	private static final int WATCH_TICKS = 30;
	private static final int PREVIEW_TICKS = 273;

	@Test
	public void previewPlaysTheRealStreamsLikeAPlayerFollowingThePlugin()
	{
		for (long seed = 0; seed < 5; seed++)
		{
			TearsGame streams = TearsGameTest.game("gggbbb", 100_000, 2, seed);
			TearsGame mirror = TearsGameTest.game("gggbbb", 100_000, 2, seed);
			StreamTracker tracker = new StreamTracker();
			int[] before = new int[Walls.COUNT];
			Planner planner = new Planner(100, 40);
			int[] shown = {-1};

			PreviewRun preview = null;
			for (int tick = 0; tick < WATCH_TICKS + PREVIEW_TICKS; tick++)
			{
				System.arraycopy(streams.colour, 0, before, 0, Walls.COUNT);
				streams.moveStreams();
				for (int wall = 0; wall < Walls.COUNT; wall++)
				{
					if (tick == 0 || streams.colour[wall] != before[wall])
					{
						tracker.wallChanged(wall, streams.colour[wall], tick);
					}
				}

				if (tick == WATCH_TICKS)
				{
					assertTrue(tracker.isComplete());
					preview = new PreviewRun(tick, PREVIEW_TICKS, TearsGameTest.ENTRANCE_X, TearsGameTest.ENTRANCE_Y, 2, planner, seed);
					mirror.endTick = tick + PREVIEW_TICKS;
				}

				if (preview != null)
				{
					preview.tick(tracker, tick);
					// The same strategy played directly: plan, hold steady, go where it points
					mirror.moveStreams();
					Planner.Plan plan = planner.plan(mirror, seed);
					shown[0] = Planner.steady(shown[0], plan, Planner.STEADY_MARGIN);
					mirror.request(shown[0]);
					mirror.finishTick();
				}
				else
				{
					mirror.moveStreams();
					mirror.tick++;
				}
				streams.tick++;
			}

			assertTrue(preview.isOver());
			assertEquals(mirror.tears, preview.getPlayer().tears);
		}
	}
}

package com.togoptimizer;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class StreamTrackerTest
{
	/**
	 * Plays a model game and reports its wall changes to a tracker, as the plugin will from the
	 * game's objects. The tracker starts watching at {@code loadTick}, when the cave loads.
	 */
	private static StreamTracker watch(String order, long seed, int loadTick, int untilTick)
	{
		TearsGame game = TearsGameTest.game(order, 10_000, 0, seed);
		StreamTracker tracker = new StreamTracker();
		int[] before = new int[Walls.COUNT];
		while (game.tick < untilTick)
		{
			System.arraycopy(game.colour, 0, before, 0, Walls.COUNT);
			game.moveStreams();
			if (game.tick == loadTick)
			{
				for (int wall = 0; wall < Walls.COUNT; wall++)
				{
					tracker.wallChanged(wall, game.colour[wall], game.tick);
				}
			}
			else if (game.tick > loadTick)
			{
				for (int wall = 0; wall < Walls.COUNT; wall++)
				{
					if (game.colour[wall] != before[wall])
					{
						tracker.wallChanged(wall, game.colour[wall], game.tick);
					}
				}
			}
			game.tick++;
		}

		// Everything the tracker claims to know must match the game
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			assertEquals("colour of wall " + wall, game.colour[wall], tracker.colour(wall));
			int next = tracker.nextMove(wall);
			if (next >= 0)
			{
				assertEquals("next move of wall " + wall, game.nextMove[wall], next);
			}
		}
		return tracker;
	}

	@Test
	public void streamsOnLoadHaveUnknownTiming()
	{
		// The game starts mid-cycle; load on its first tick, before any real move is seen
		StreamTracker tracker = watch("gggbbb", 1, 0, 1);

		assertFalse(tracker.isComplete());
		assertNull(tracker.getOrder());
	}

	@Test
	public void oneCycleIsEnoughToKnowEverything()
	{
		for (long seed = 0; seed < 50; seed++)
		{
			// Load partway through a cycle, then watch for just over one more
			int load = (int) (seed % 16);
			StreamTracker tracker = watch("gggbbb", seed, load, load + 16 + 6);

			assertTrue("seed " + seed, tracker.isComplete());
			assertEquals("gggbbb", tracker.getOrder());
		}
	}

	@Test
	public void detectsOtherOrders()
	{
		for (String order : new String[]{"bgbgbg", "bbbggg", "gbbgbg"})
		{
			assertEquals(order, watch(order, 7, 5, 5 + 16 + 6).getOrder());
		}
	}

	@Test
	public void aCycleCutShortByLoadingIsNotAnOrder()
	{
		// The model's game starts as the first blue moves (tick 0), so blues move on ticks 0 to 2 and
		// greens on 13 to 15. Loading on tick 1 sees only part of that cycle.
		StreamTracker tracker = watch("gggbbb", 3, 1, 12);

		assertNull(tracker.getOrder());
	}

	@Test
	public void measuresHowLongStreamsLast()
	{
		StreamTracker tracker = watch("gggbbb", 4, 0, 40);

		assertEquals(TearsGame.STREAM_LIFE, tracker.getLastLife());
	}

	@Test
	public void fillsAGameWithTheTrackedStreams()
	{
		StreamTracker tracker = watch("gggbbb", 8, 3, 30);
		TearsGame game = new TearsGame();

		tracker.fill(game);

		int[] colours = new int[Walls.COUNT];
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			colours[wall] = tracker.colour(wall);
		}
		assertArrayEquals(colours, game.colour);
	}

	@Test
	public void resetForgetsEverything()
	{
		StreamTracker tracker = watch("gggbbb", 2, 0, 30);
		tracker.reset();

		assertFalse(tracker.isComplete());
		assertNull(tracker.getOrder());
		assertEquals(-1, tracker.getLastLife());
	}
}

package com.togoptimizer;

import java.util.Random;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TearsGameTest
{
	static final int ENTRANCE_X = 3257;
	static final int ENTRANCE_Y = 9517;

	static TearsGame game(String order, int ticks, int reaction, long seed)
	{
		return start(order, ticks, ENTRANCE_X, ENTRANCE_Y, reaction, new Random(seed));
	}

	/**
	 * A game with streams on random walls, starting as the first blue in {@code order} moves, which
	 * is when the wiki suggests entering.
	 *
	 * @param order colours in the order the six streams move each cycle, such as "gggbbb"
	 */
	static TearsGame start(String order, int ticks, int startX, int startY, int reaction, Random rng)
	{
		TearsGame game = new TearsGame();
		game.endTick = ticks;
		game.x = startX;
		game.y = startY;
		game.reaction = reaction;
		game.rng = rng;

		int firstBlue = order.indexOf('b');
		boolean[] used = new boolean[Walls.COUNT];
		for (int stream = 0; stream < order.length(); stream++)
		{
			int wall;
			do
			{
				wall = rng.nextInt(Walls.COUNT);
			}
			while (used[wall]);
			used[wall] = true;
			game.colour[wall] = order.charAt(stream) == 'b' ? TearsGame.BLUE : TearsGame.GREEN;
			game.nextMove[wall] = Math.floorMod(stream - firstBlue, TearsGame.STREAM_LIFE);
		}
		return game;
	}

	@Test
	public void wallsAreFoundByTile()
	{
		assertEquals(0, Walls.at(3257, 9514));
		assertEquals(4, Walls.at(3261, 9517));
		assertEquals(8, Walls.at(3259, 9520));
		assertEquals(-1, Walls.at(3258, 9517));
	}

	@Test
	public void travelIsOneTileATick()
	{
		// Neighbouring walls on the south side
		assertEquals(1, Walls.travel(Walls.standX(0), Walls.standY(0), 1));
		// South-west corner to north-east corner, four tiles
		assertEquals(4, Walls.travel(Walls.standX(0), Walls.standY(0), 8));
		assertEquals(0, Walls.travel(Walls.standX(3), Walls.standY(3), 3));
	}

	@Test
	public void streamsKeepTheirColoursAndNeverShare()
	{
		TearsGame game = game("gggbbb", 1000, 0, 1);
		for (int i = 0; i < 1000; i++)
		{
			game.step(g -> -1);
			int blue = 0;
			int green = 0;
			for (int c : game.colour)
			{
				blue += c == TearsGame.BLUE ? 1 : 0;
				green += c == TearsGame.GREEN ? 1 : 0;
			}
			assertEquals(3, blue);
			assertEquals(3, green);
		}
	}

	@Test
	public void anotherBlueLandsOnYourWallFiveTimesInNine()
	{
		// The wiki: after the first blue leaves the player's wall, there is a 5/9 chance one of the
		// other two blues lands there
		int trials = 20_000;
		int landed = 0;
		for (int seed = 0; seed < trials; seed++)
		{
			TearsGame game = game("gggbbb", 1000, 0, seed);
			// The game starts as the first blue moves, so its current wall is where it just left
			int left = firstBlueWallBeforeMoving(game);
			game.moveStreams();
			game.tick++;
			game.moveStreams();
			boolean second = game.colour[left] == TearsGame.BLUE;
			game.tick++;
			game.moveStreams();
			if (second || game.colour[left] == TearsGame.BLUE)
			{
				landed++;
			}
		}
		assertEquals(5 / 9.0, landed / (double) trials, 0.01);
	}

	private static int firstBlueWallBeforeMoving(TearsGame game)
	{
		for (int wall = 0; wall < Walls.COUNT; wall++)
		{
			if (game.colour[wall] == TearsGame.BLUE && game.nextMove[wall] == game.tick)
			{
				return wall;
			}
		}
		throw new AssertionError("no blue due to move");
	}

	@Test
	public void nearestBlueScoresAsCalibrated()
	{
		// With timings measured in game (273 QP, two-tick reactions), where a player scored 191 playing
		// well, going to the nearest blue averages about 168
		double total = 0;
		int games = 200;
		for (int seed = 0; seed < games; seed++)
		{
			TearsGame game = game("gggbbb", 273, 2, seed);
			game.runUntil(273, TearsGame::nearestBlue);
			total += game.tears;
		}
		assertEquals(168.0, total / games, 2);
	}

	@Test
	public void noTearsAreCollectedWhileWalking()
	{
		TearsGame game = game("gggbbb", 100, 0, 3);
		game.step(TearsGame::nearestBlue);
		// The entrance is a tile or two from every wall, then collecting starts a tick after arriving
		assertEquals(0, game.tears);
		assertTrue(game.readyTick > game.tick - 1);
	}
}

